UPDATE human_request SET status = 'EXPIRED',
resolved_at = CURRENT_TIMESTAMP WHERE tenant_id = #{tenantId}
AND business_id = #{id} AND status = 'PENDING'

UPDATE project_message SET message_text = CONCAT(message_text,
'\nHuman clarification: ', #{answer})
WHERE business_id = #{messageId} AND tenant_id = #{tenantId}

UPDATE coordinator_dispatch SET status = 'PENDING',
available_at = CURRENT_TIMESTAMP, lease_owner = NULL,
lease_expires_at = NULL WHERE business_id = #{dispatchId}
AND tenant_id = #{tenantId}
